script:
frappe.listview_settings['ToDo'] = {
  add_fields: ['reference_type', 'reference_name'],
  formatters: {
    description: function(value, df, doc) {
      var text = value || '';
      if (doc.reference_type === 'Lead' && doc.reference_name) {
        var safe_lead = frappe.utils.escape_html(doc.reference_name);
        var href = '/app/lead-activity/' + encodeURIComponent(doc.reference_name);
        var style = 'background:#1B5EA0;color:#fff;margin-right:8px;padding:2px 8px;font-size:11px;font-weight:500;text-decoration:none;border-radius:3px;display:inline-block;vertical-align:middle;line-height:1.5;';
        var badge = '<a href="' + href + '" class="nest-lead-badge" onclick="event.stopPropagation();" title="Open Lead Activity Hub for ' + safe_lead + '" style="' + style + '"><i class="fa fa-user" style="margin-right:4px;"></i>' + safe_lead + '</a>';
        return badge + text;
      }
      return text;
    }
  }
};

frappe.ui.form.on('ToDo', {
  refresh: function(frm) {
    // Show a 'Back to My Activities' button on every ToDo form so sales reps
    // who drilled in from /desk/my-activities have a one-click way home.
    // Custom buttons accumulate across renders — clear our previous button first.
    frm.page.remove_inner_button && frm.page.remove_inner_button(__('My Activities'));
    frm.page.set_secondary_action('<i class="fa fa-arrow-left" style="margin-right:6px;"></i>My Activities', function() {
      frappe.set_route('my-activities');
    });
    // If the user has a CRM Lead reference, also offer a direct jump to the Lead Activity Hub.
    if (frm.doc.reference_type === 'Lead' && frm.doc.reference_name) {
      frm.add_custom_button(__('Lead Activity Hub'), function() {
        frappe.set_route('lead-activity', frm.doc.reference_name);
      });
    }
  }
});
